const body = $input.item.json.body || $input.item.json || {};
const topic = body.topic || body.message || 'general technology trends';
const depth = body.depth || 'summary';

const systemPrompt = `You are HomeBot Research Assistant. Your job is to provide thorough, well-structured research on any topic the user asks about.\n\nFormat your response as:\n## Research: [Topic]\n### Key Points\n- Bullet points of main findings\n### Detailed Analysis\nParagraph-form analysis with specifics\n### Sources & Further Reading\nSuggest where to find more info\n\nBe factual, cite specifics where possible, and note any limitations in your knowledge. Depth level: ${depth}.`;

return {
  json: {
    model: 'qwen2.5:7b',
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: `Research the following topic thoroughly: ${topic}` }
    ],
    stream: false
  }
};

const ollamaRes = $input.item.json;
const content = ollamaRes.message?.content || ollamaRes.response || 'Research unavailable';
return {
  json: {
    output: content,
    data: { assistant: { role: 'assistant', content } }
  }
};
